<script setup>
import {computed,ref} from 'vue';import {useWorkspace} from '../stores/workspace.js';import Icon from '../components/Icon.vue';import {statuses,modes} from '../data/seed.js';import {metrics,money} from '../utils/shipments.js';
const store=useWorkspace(),period=ref('all');const items=computed(()=>store.shipments.filter(s=>period.value==='all'||s.created.startsWith(period.value)));const stats=computed(()=>metrics(items.value));const distribution=computed(()=>statuses.map(status=>({status,count:items.value.filter(s=>s.status===status).length})));const modeStats=computed(()=>modes.map(mode=>({mode,count:items.value.filter(s=>s.mode===mode).length,weight:items.value.filter(s=>s.mode===mode).reduce((n,s)=>n+s.weight,0)})));const months=computed(()=>{const keys=[...new Set(store.shipments.map(s=>s.created.slice(0,7)))].sort().slice(-6);return keys.map(key=>({key,label:new Date(key+'-01').toLocaleDateString('en',{month:'short',timeZone:'UTC'}),count:items.value.filter(s=>s.created.startsWith(key)).length}));});const maxCount=computed(()=>Math.max(1,...months.value.map(m=>m.count)));const customers=computed(()=>{const groups=new Map();for(const s of items.value){const c=groups.get(s.customer)||{name:s.customer,count:0,value:0};c.count++;c.value+=s.value;groups.set(s.customer,c);}return[...groups.values()].sort((a,b)=>b.count-a.count);});const ring=computed(()=>{const colors=['#b7bfcb','#4e8ed1','#a994ce','#368366','#df9b51'];let prev=0;return 'conic-gradient('+distribution.value.map((d,i)=>{const start=prev;prev+=stats.value.total?d.count/stats.value.total*100:0;return `${colors[i]} ${start}% ${prev}%`;}).join(',')+')';});
</script>
<template><div class="page-heading"><div><div class="greeting">TURN MOVEMENT INTO INSIGHT</div><h1>The bigger picture.</h1><p>Understand the patterns behind your operations.</p></div><label class="period-picker"><Icon name="CalendarDays" :size="15"/><select v-model="period" aria-label="Analytics period"><option value="all">All time</option><option value="2026-10">October 2026</option><option value="2026-09">September 2026</option><option value="2026-08">August 2026</option></select></label></div><div class="metric-grid analytics-metrics"><article class="metric-card"><div><span>Total shipment value</span><Icon name="Package"/></div><strong>{{money(stats.value)}}</strong><p>Declared value of selected shipments</p></article><article class="metric-card"><div><span>Total freight weight</span><Icon name="Box"/></div><strong>{{(stats.weight/1000).toFixed(1)}} <small>tonnes</small></strong><p>Across all transport modes</p></article><article class="metric-card"><div><span>Delivered share</span><Icon name="CircleCheck"/></div><strong>{{stats.rate}}<small>%</small></strong><p>{{stats.delivered}} delivered of {{stats.total}} shipments</p></article></div><div class="analytics-grid"><section class="panel volume-panel"><div class="panel-heading"><div><h2>Shipment volume</h2><p>Shipments grouped by booking month.</p></div><span class="chart-legend"><i></i>Bookings</span></div><div class="bar-chart" role="img" :aria-label="months.map(m=>m.label+': '+m.count+' shipments').join(', ')"><div class="chart-grid"><span v-for="i in [4,3,2,1,0]">{{Math.round(maxCount*i/4)}}</span></div><div class="chart-columns"><div v-for="m in months" class="bar-column"><span class="bar-count">{{m.count}}</span><div class="bar" :style="{height:Math.max(2,m.count/maxCount*180)+'px'}" :title="`${m.key}: ${m.count} shipments`"></div><span class="bar-label">{{m.label}} '{{m.key.slice(2,4)}}</span></div></div></div></section><section class="panel distribution-panel"><div class="panel-heading"><div><h2>Status breakdown</h2><p>Where things stand right now.</p></div></div><div class="donut-layout"><div class="donut" :style="{background:stats.total?ring:'#e8ecef'}" role="img" :aria-label="distribution.map(d=>d.status+': '+d.count).join(', ')"><div><strong>{{stats.total}}</strong><span>Shipments</span></div></div><div class="donut-legend"><div v-for="d in distribution"><span class="legend-dot" :class="d.status.toLowerCase().replaceAll(' ','-')"></span><span>{{d.status}}</span><b>{{d.count}}</b></div></div></div></section><section class="panel"><div class="panel-heading"><div><h2>Transport mix</h2><p>The modes that move your business.</p></div></div><div class="transport-stats"><div v-for="m in modeStats"><span class="mode-icon"><Icon :name="m.mode==='Ocean'?'Ship':m.mode==='Road'?'Truck':'Plane'"/></span><div><b>{{m.mode}} freight</b><span>{{(m.weight/1000).toFixed(1)}} tonnes</span></div><strong>{{m.count}}</strong><span class="muted">{{stats.total?Math.round(m.count/stats.total*100):0}}%</span></div></div></section><section class="panel"><div class="panel-heading"><div><h2>Customer activity</h2><p>Ranked by number of shipments.</p></div></div><div class="customer-stats"><div v-for="(c,i) in customers"><span class="customer-rank">{{String(i+1).padStart(2,'0')}}</span><span>{{c.name}}<small>{{money(c.value)}} declared value</small></span><b>{{c.count}}<small>shipments</small></b></div><p v-if="!customers.length" class="empty-small">No activity for the selected period.</p></div></section></div><p class="page-footnote"><Icon name="Circle" :size="10"/>All figures are calculated from your current workspace. Shipment value is not revenue.</p></template>
